module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg [7:0] in;
    wire [7:0] out;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .in(in),
        .out(out)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;

    initial begin
        // Test case 1: Reverse of 00000000 should be 00000000
        in = 8'b00000000; #10;
        if (out !== 8'b00000000) errors = errors + 1;

        // Test case 2: Reverse of 11111111 should be 11111111
        in = 8'b11111111; #10;
        if (out !== 8'b11111111) errors = errors + 1;

        // Test case 3: Reverse of 10101010 should be 01010101
        in = 8'b10101010; #10;
        if (out !== 8'b01010101) errors = errors + 1;

        // Test case 4: Reverse of 11001100 should be 00110011
        in = 8'b11001100; #10;
        if (out !== 8'b00110011) errors = errors + 1;

        // Test case 5: Reverse of 00001111 should be 11110000
        in = 8'b00001111; #10;
        if (out !== 8'b11110000) errors = errors + 1;

        // Test case 6: Reverse of 01100110 should be 01100110
        in = 8'b01100110; #10;
        if (out !== 8'b01100110) errors = errors + 1;

        // Test case 7: Reverse of 00010001 should be 10010000
        in = 8'b00010001; #10;
        if (out !== 8'b10010000) errors = errors + 1;

        // Test case 8: Reverse of 11100000 should be 00001111
        in = 8'b11100000; #10;
        if (out !== 8'b00001111) errors = errors + 1;

        // Final check for errors
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

